// JQL (Jira Query Language) examples

// All open issues in current sprint
project = MOB AND sprint in openSprints() AND resolution = Unresolved

// My open issues
assignee = currentUser() AND resolution = Unresolved

// High priority bugs
project = MOB AND issuetype = Bug AND priority in (Highest, High) AND resolution = Unresolved

// Issues completed last sprint
project = MOB AND sprint in completedSprints() AND status changed to Done during sprint

// Issues in current epic
"Epic Link" = MOB-123

// Issues without story points
project = MOB AND issuetype in (Story, Task, Bug) AND "Story Points" is EMPTY

// Issues created in last 7 days
created >= -7d

// Issues updated today
updated >= startOfDay()

// Blocked issues
status = Blocked

// Issues for specific version
fixVersion = 2.5.0

// Combine with AND/OR
project = MOB AND (assignee = jsmith OR reporter = jsmith)

// Use in dashboards and filters
